exercise.starter:
-- Top three per genre
WITH counts AS (
  SELECT b.genre, b.title, count(*) AS loan_count
  FROM books b JOIN loans l ON l.book_id = b.id
  GROUP BY b.id, b.genre, b.title
), ranked AS (
  SELECT *, row_number() OVER (PARTITION BY genre ORDER BY loan_count DESC) AS loan_rank
  FROM counts
)
SELECT genre, title, loan_count, loan_rank FROM ranked WHERE loan_rank <= 3;

exercise.solution:
WITH counts AS (
  SELECT b.genre, b.title, count(*) AS loan_count
  FROM books b JOIN loans l ON l.book_id = b.id
  GROUP BY b.id, b.genre, b.title
), ranked AS (
  SELECT *, rank() OVER (PARTITION BY genre ORDER BY loan_count DESC) AS loan_rank
  FROM counts
)
SELECT genre, title, loan_count, loan_rank FROM ranked WHERE loan_rank <= 3;

